export const TODAY = '2026-10-28'; // Reproducible demonstration date, not a live clock.
export const statusLabels={pending:'ஆய்வில் உள்ளது',approved:'ஒப்புதல்',returned:'திருப்பப்பட்டது',rejected:'நிராகரிப்பு'};
const names=['மீனா குமாரி','செந்தில் குமார்','கலைச்செல்வி','முகமது இம்ரான்','லட்சுமி தேவி','அருண் பிரசாத்','பாத்திமா பானு','சரவணன்','கவிதா ராஜன்','ரமேஷ் கண்ணன்','மேரி ஜோசப்','பிரியா செல்வம்'];
const places=['அவனியாபுரம்','திருப்பரங்குன்றம்','விளாச்சேரி','திருநகர்'];
export function seed(){return names.map((name,i)=>({id:`REV-103-${String(2418+i)}`,name,village:places[i%4],submitted:`2026-10-${String([8,12,14,15,17,18,19,20,21,22,23,25][i]).padStart(2,'0')}`,income:[96000,144000,72000,180000,84000,120000,108000,156000,60000,132000,192000,90000][i],evidenceIncome:i===1?168000:i===3?204000:[96000,144000,72000,180000,84000,120000,108000,156000,60000,132000,192000,90000][i],members:[3,4,2,5][i%4],occupation:i%2?'தனியார் நிறுவன ஊழியர்':'தினக்கூலி',purpose:i%3?'கல்வி உதவித்தொகை':'கல்விக் கட்டணச் சலுகை',status:'pending',docs:[{key:'photo',title:'விண்ணப்பதாரர் புகைப்படம்',present:true},{key:'address',title:'முகவரிச் சான்று',present:true},{key:'family',title:'குடும்ப அட்டை',present:i!==2},{key:'declaration',title:'சுய உறுதிமொழி',present:i!==4},{key:'income',title:i%2?'சம்பளச் சான்று':'வருமான விவர அறிக்கை',present:i!==0&&i!==6}],history:[]}));}
export function age(a){return Math.floor((Date.parse(TODAY)-Date.parse(a.submitted))/86400000);}
export function assess(a){const missing=a.docs.filter(d=>!d.present);const inconsistent=a.evidenceIncome!==a.income&&a.docs.find(d=>d.key==='income').present;const issues=missing.map(d=>`${d.title} இணைக்கப்படவில்லை.`);if(inconsistent)issues.push(`விண்ணப்ப வருமானம் ₹${a.income.toLocaleString('en-IN')}; வருமான ஆதாரத்தில் ₹${a.evidenceIncome.toLocaleString('en-IN')}. விளக்கம் தேவை.`);return {missing,inconsistent,issues,suggestion:issues.length?'returned':'approved',reason:issues.length?issues.join(' '):'மாதிரி சரிபார்ப்பில் தேவையான ஆவணங்கள் உள்ளன; விண்ணப்பம் மற்றும் வருமான ஆதாரத்தில் உள்ள தொகைகள் பொருந்துகின்றன. அசல் ஆவணங்களின் நம்பகத்தன்மையை அலுவலர் சரிபார்க்க வேண்டும்.'};}
export function priority(a){return age(a)>=15?'overdue':assess(a).issues.length?'attention':'normal';}
export function decide(a,status,reason,verified){if(a.status!=='pending')throw new Error('இந்த விண்ணப்பத்தில் ஏற்கனவே முடிவு பதிவாகியுள்ளது.');if(!['approved','returned','rejected'].includes(status))throw new Error('செல்லாத முடிவு.');if(!verified||reason.trim().length<12)throw new Error('ஆவணங்களைச் சரிபார்த்து, குறைந்தது 12 எழுத்துகளில் காரணத்தை எழுதவும்.');return {...a,status,history:[...a.history,{status,reason:reason.trim(),officer:'அ. தமிழ்ச்செல்வி',at:new Date().toISOString()}]};}
